import math

def evaluate_expression(a):
    # The expression is a * floor(22*a * floor(22*a * floor(22*a)))
    inner_floor = math.floor(22 * a)
    middle_floor = math.floor(22 * a * inner_floor)
    outer_result = a * math.floor(22 * a * middle_floor)
    return outer_result, inner_floor

def test_range(start, end, step):
    results = []
    a_values = [round(x, 4) for x in [start + i * step for i in range(int(((end - start) / step) + 1))]]

    print(f"--- Testing range [{start}, {end}] with step {step} ---")
    for a in a_values:
        result, inner_floor = evaluate_expression(a)
        # Check if the result is close to 4 (tolerance of 1e-3)
        if abs(result - 4.0) < 1e-3:
            results.append({
                'a': a,
                'result': result,
                'inner_floor': inner_floor
            })
    return results

# Test ranges
results_01_1 = test_range(0.1, 1.0, 0.01)
results_1_10 = test_range(1.0, 10.0, 0.01)

print("\nResults [0.1, 1.0]:")
if results_01_1:
    for r in results_01_1:
        print(f"a = {r['a']}, Result = {r['result']}, floor(22a) = {r['inner_floor']}")
else:
